const event = $('Receber evento Ecojoi').first().json.body;
if (!event || event.event !== 'ecojoi.crm.message.received' || event.attendance_state !== 'automatic' || event.channel !== 'whatsapp') return [];
if (event.tenant_id !== 'cbff399f-19ae-438b-b6cf-b94d166a8ce8' || !/^[0-9a-f-]{36}$/i.test(event.conversation_id ?? '')) return [];
const history = Array.isArray(event.messages) ? event.messages.slice(-30) : [];
if (history.at(-1)?.direction !== 'inbound') return [];
const provider = $('Escolher provedor').first().json.provider;
if (!['openai', 'gemini'].includes(provider)) throw new Error('Selecione openai ou gemini');
const knowledge = Array.isArray(event.knowledge) ? event.knowledge.filter(d => d?.text).map(d => ({name: String(d.name ?? ''), text: String(d.text)})) : [];
const messages = history.map(m => ({direction:m.direction, type:m.message_type ?? 'text', text:String(m.body ?? '').slice(0,3500)}));
const config = event.agent_config ?? {};
const userContext = JSON.stringify({history:messages,knowledge,config:{tone:config.tone, objective:config.objective, rules:config.rules, human_handoff_keywords:config.human_handoff_keywords}});
return [{json:{provider,tenant_id:event.tenant_id,conversation_id:event.conversation_id,userContext}}];

const data = $input.first().json;
const context = $('Preparar contexto').first().json;
const openai = context.provider === 'openai';
const raw = openai ? data.choices?.[0]?.message?.content : data.candidates?.[0]?.content?.parts?.filter(p => !p.thought).map(p => p.text ?? '').join('');
if (typeof raw !== 'string' || !raw.trim()) throw new Error('Provedor não retornou texto');
const answer = JSON.parse(raw);
const body = typeof answer.body === 'string' ? answer.body.trim().slice(0,2500) : '';
if (!body) throw new Error('Resposta vazia');
return [{json:{tenant_id:context.tenant_id, conversation_id:context.conversation_id,body,summary:typeof answer.summary === 'string' ? answer.summary.slice(0,2000) : null,next_action:typeof answer.next_action === 'string' ? answer.next_action.slice(0,500) : null,usage:{provider:context.provider,model:openai ? (data.model ?? 'gpt-4.1-mini') : (data.modelVersion ?? 'gemini-2.5-flash'), input_tokens:openai ? (data.usage?.prompt_tokens ?? 0) : (data.usageMetadata?.promptTokenCount ?? 0),output_tokens:openai ? (data.usage?.completion_tokens ?? 0) : (data.usageMetadata?.candidatesTokenCount ?? 0)}}}];
